   }
@@ -72,3 +74,40 @@ function validatePingMessage(message: Record<string, unknown>): ValidationResult
     },
   };
 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  if (message.limit !== undefined && (!Number.isInteger(message.limit) || message.limit < 0 || message.limit > 200)) {
+    return {valid: false, error: 'list_sessions limit must be a non-negative integer no greater than 200'};
+  }
+
+  if (message.before !== undefined) {
+    const before = message.before;
+    if (typeof before !== 'object' || before === null) {
+      return {valid: false, error: 'list_sessions before must be an object'};
+    }
+
+    const cursor = before as Record<string, unknown>;
+    if (typeof cursor.sessionId !== 'string' || cursor.sessionId.length < 1 || cursor.sessionId.length > 128) {
+      return {valid: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
+    }
+
+    if (!isValidDate(cursor.updatedAt)) {
+      return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
+    }
+  }
+
+  return {
+    valid: true,
+    data: {
+      type: 'list_sessions',
+      limit: message.limit as number | undefined,
+      before: message.before as ListSessionsMessage['before'],
+    },
+  };
+}
+
+function isValidDate(value: unknown): boolean {
+  if (typeof value === 'string') return !Number.isNaN(Date.parse(value));
+  if (typeof value === 'number') return Number.isFinite(value) && !Number.isNaN(new Date(value).getTime());
+  return false;
+}
